class Solution {
  public String lexSmallest(String s) {
    int n = s.length();
    String best = null;
    for (int k = 1; k <= n; k++) {
      String a = new StringBuilder(s.substring(0, k)).reverse() + s.substring(k);
      String b = s.substring(0, n - k) + new StringBuilder(s.substring(n - k)).reverse();
      if (best == null || a.compareTo(best) < 0) best = a;
      if (b.compareTo(best) < 0) best = b;
    }
    return best;
  }
}
